        if (token_ != launchToken0 && token_ != launchToken1) return;
        SeLib.warpPastPonsV1Restrictions(token_);
        ISwapRouter router = ponsV1.swapRouter;
        for (uint256 i; i < 16 && IERC20(token_).balanceOf(to_) < amount_; ++i) {
