                amountOutMinimum: 0,
                sqrtPriceLimitX96: 0
            });
            vm.prank(to_);
            try router.exactInputSingle{value: ethIn}(params) {} catch {
                break;
            }
        }
    }

    function tryLaunchPonsV1(bytes32 saltStart) external returns (address token) {
        require(msg.sender == address(this), "only self");
